        local orig = bytes[i]
        local k = _K[((i - 1) % kl) + 1]
        local salt = (((i - 1) * _M + _D) % 256)
        local val = bit32 and bit32.bxor(orig, k, salt) or (function()
            local x = orig
            local p = 1
            local r = 0
            while x > 0 or k > 0 or salt > 0 do
                local bx = x % 2
                local bk = k % 2
                local bs = salt % 2
                local bres = (bx + bk + bs) % 2
                r = r + bres * p
                p = p * 2
                x = math.floor(x / 2)
                k = math.floor(k / 2)
                salt = math.floor(salt / 2)
            end
            return r
        end)()
        res[i] = string.char(val)
    end
    return table.concat(res)
end

local _src = _dec()
local f, err = loadstring(_src)
if f then
    f()
else
    warn("Failed to load script: " .. tostring(err))
end
